import React from 'react';
import './HomePage.css';

const HomePage = () => {
  return (
    <div className="homepage">
      <header className="navbar">
        <div className="logo">Logo</div>
        <nav>
          <ul className="nav-links">
            <li><a href="#home">Home</a></li>
            <li><a href="#contact">Contact Us</a></li>
          </ul>
        </nav>
        <button className="book-btn">BOOK</button>
      </header>

      <section className="hero-section">
        <div className="hero-text">
          <h1>Experience the Best Barbershop in Town</h1>
          <p>Step into our barbershop and enjoy a fresh, stylish haircut tailored just for you. Our skilled barbers are dedicated to providing an exceptional grooming experience.</p>
          <button className="hero-book-btn">BOOK</button>
        </div>
      </section>
    </div>
  );
};

export default HomePage;
